class Solution:
    def maxScore(self, nums: List[int]) -> int:
        nums.sort(reverse=True)
        s = cnt = 0
        for x in nums:
            if s + x > 0:
                s += x
                cnt += 1
            else:
                break
        return cnt

c.cpp:
class Solution {
public:
    int maxScore(vector<int>& nums) {
        sort(nums.rbegin(), nums.rend());
        long long s = 0;
        int cnt = 0;
        for (int x : nums) {
            if (s + x > 0) { s += x; cnt++; }
            else break;
        }
        return cnt;
    }
};

c.java:
class Solution {
    public int maxScore(int[] nums) {
        Arrays.sort(nums);
        long s = 0;
        int cnt = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            if (s + nums[i] > 0) { s += nums[i]; cnt++; }
            else break;
        }
        return cnt;
    }
}

